def semver_sort(versions):
    def parse(v):
        main_part = v
        build = None
        if '+' in v:
            # build metadata starts at first '+' that comes after core version
            # but need to be careful: '-' could occur before '+', find first '+'
            plus_idx = v.find('+')
            main_part = v[:plus_idx]
            build = v[plus_idx+1:]
        # find prerelease: first '-' in main_part after core version numbers
        core = main_part
        prerelease = None
        dash_idx = main_part.find('-')
        if dash_idx != -1:
            core = main_part[:dash_idx]
            prerelease = main_part[dash_idx+1:]
        parts = core.split('.')
        major, minor, patch = int(parts[0]), int(parts[1]), int(parts[2])
        return major, minor, patch, prerelease

    def ident_key(ident):
        if ident.isdigit():
            return (0, int(ident))
        else:
            return (1, ident)

    def make_key(v):
        major, minor, patch, prerelease = parse(v)
        if prerelease is None:
            has_pre_flag = 1
            pre_key = ()
        else:
            has_pre_flag = 0
            idents = prerelease.split('.')
            pre_key = tuple(ident_key(i) for i in idents)
        return (major, minor, patch, has_pre_flag, pre_key)

    return sorted(versions, key=make_key)

